function Get-MtLicenseSkipReason {
    <#
    .SYNOPSIS
    Builds the skip message and the 2.x skip code for an unmet License, from Get-MtLicenseRequirementGap rows.
    .DESCRIPTION
    Licences are named by their DisplayName in the licence table; a token the table does not have (a custom
    test's plan name) keeps its own name. One element reads "requires X and Y"; several read "requires X or Y",
    or "requires one of: X; or Y and Z" when an element joins licences.

    What the tenant lacks: when it has none of the licences named, the message says so. Otherwise it names the
    licences missing from the closest element, the one with the fewest missing (the first on a tie), since
    adding those is the shortest way to meet the requirement. The 2.x code is that of the first missing token
    of the closest element that has one, else 'Custom'.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)] [object[]] $Gap
    )

    $table = Get-MtLicenseTable
    $entryOf = { param($token) foreach ($key in $table.Tokens.Keys) { if ($key -eq $token) { return $table.Tokens[$key] } } }
    $nameOf = { param($token) $entry = & $entryOf $token; if ($entry -and $entry.DisplayName) { $entry.DisplayName } else { $token } }
    $join = {
        param([string[]] $Names)
        switch ($Names.Count) {
            1 { $Names[0] }
            2 { "$($Names[0]) and $($Names[1])" }
            default { ($Names[0..($Names.Count - 2)] -join ', ') + ", and $($Names[-1])" }
        }
    }

    $elements = @($Gap | ForEach-Object { , @($_.Tokens | ForEach-Object { & $nameOf $_ }) })
    $required = if ($elements.Count -eq 1) {
        & $join $elements[0]
    } elseif (-not ($elements | Where-Object { $_.Count -gt 1 })) {
        $names = @($elements | ForEach-Object { $_[0] })
        if ($names.Count -eq 2) { "$($names[0]) or $($names[1])" } else { ($names[0..($names.Count - 2)] -join ', ') + ", or $($names[-1])" }
    } else {
        'one of: ' + (@($elements | ForEach-Object { & $join $_ }) -join '; or ')
    }

    $allTokens = @($Gap.Tokens | Select-Object -Unique)
    $allMissing = @($Gap.Missing | Select-Object -Unique)
    $closest = $Gap | Sort-Object -Stable { $_.Missing.Count } | Select-Object -First 1
    $lacks = if ($allMissing.Count -eq $allTokens.Count) {
        switch ($allTokens.Count) { 1 { 'The tenant does not have it.' } 2 { 'The tenant has neither.' } default { 'The tenant has none of them.' } }
    } else {
        "The tenant does not have $(& $join @($closest.Missing | ForEach-Object { & $nameOf $_ }))."
    }

    $legacy = 'Custom'
    foreach ($token in $closest.Missing) {
        $entry = & $entryOf $token
        if ($entry -and $entry.LegacySkipCode) { $legacy = $entry.LegacySkipCode; break }
    }
    [pscustomobject]@{ Detail = "This test requires $required. $lacks"; LegacySkipCode = $legacy }
}

